+// detectPython recognises a Python project by a tracked root pyproject.toml or requirements.txt, each
+// with its text in files. The ruff and pytest configuration files count only through tracked.
+func detectPython(d *Detected, files map[string]string, tracked []string) {
+	pyproject, hasPyproject := files["pyproject.toml"]
+	hasPyproject = hasPyproject && slices.Contains(tracked, "pyproject.toml")
+	requirements, hasRequirements := files["requirements.txt"]
+	hasRequirements = hasRequirements && slices.Contains(tracked, "requirements.txt")
+	if !hasPyproject && !hasRequirements {
+		return
+	}
+	if hasRequirements {
+		d.Setup = append(d.Setup, "python -m pip install -r requirements.txt")
+	} else {
+		d.Setup = append(d.Setup, "python -m pip install -e .")
+	}
+	if (hasPyproject && strings.Contains(pyproject, "pytest")) || (hasRequirements && strings.Contains(requirements, "pytest")) {
+		d.Checks = append(d.Checks, Check{"python-test", "pytest"})
+	}
+	if (hasPyproject && strings.Contains(pyproject, "[tool.ruff")) || slices.Contains(tracked, "ruff.toml") || slices.Contains(tracked, ".ruff.toml") {
+		d.Checks = append(d.Checks, Check{"python-lint", "python -m ruff check ."})
+	}
+	for _, protected := range []string{"ruff.toml", ".ruff.toml", "pytest.ini"} {
+		if slices.Contains(tracked, protected) {
+			d.Protect = append(d.Protect, protected)
+		}
 	}
 }

